insert into anstws_ddo
       (ID, ID_CIVDDO, ID_ANSTWS, SEQUENZA, VERSION, ID_ANST03, FLAG_OBBLIGATORIO, TIPO_DOCUMENTO)
select to_number(null),
       ddo.id,
       'R001_V',
       '110',
       0,
       '52111',
       'S',
       ''
  from civddo ddo
 where ddo.cod_do      = '63'
   and ddo.tipo_atto   = 1
   and ddo.codice_ansc = 63
   and not exists (select 1 from anstws_ddo b
                    where b.id_civddo = ddo.id
                      and b.id_anstws = 'R001_V'
                      and b.id_anst03 = '52111'
                      and nvl(b.flag_obbligatorio,'N') = 'S'
                      and nvl(b.tipo_documento,' ') = ' '
                   )
/
