select to_number(null),
       ddo.id,
       'R001_V',
       '650',
       0,
       '311111',
       '',
       ''
  from civddo ddo
 where ddo.cod_do      = '104'
   and ddo.tipo_atto   = 4
   and ddo.codice_ansc = 104
   and not exists (select 1 from anstws_ddo b
                    where b.id_civddo = ddo.id
                      and b.id_anstws = 'R001_V'
                      and b.id_anst03 = '311111'
                      and nvl(b.flag_obbligatorio,'N') = 'N'
                      and nvl(b.tipo_documento,' ') = ' '
                   )
/
