select to_number(null),
       ddo.id,
       'R001_U',
       '650',
       0,
       '312121',
       '',
       ''
  from civddo ddo
 where ddo.cod_do      = '106'
   and ddo.tipo_atto   = 4
   and ddo.codice_ansc = 106
   and not exists (select 1 from anstws_ddo b
                    where b.id_civddo = ddo.id
                      and b.id_anstws = 'R001_U'
                      and b.id_anst03 = '312121'
                      and nvl(b.flag_obbligatorio,'N') = 'N'
                      and nvl(b.tipo_documento,' ') = ' '
                   )
/
